16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	
40	    @Column(name = "title")
41	    private String title;
42	
43	    @Column(name = "address")
44	    @NotEmpty
45	    private String address;
46	
47	    @Column(name = "address_line1")
48	    private String addressLine1;
49	
50	    @Column(name = "address_line2")
51	    private String addressLine2;
52	
53	    @Column(name = "city")
54	    @NotEmpty
55	    private String city;
56	
57	    @Column(name = "telephone")
58	    @NotEmpty
59	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form")
60	    private String telephone;
61	
62	    @Column(name = "email")
63	    @Email
64	    private String email;
65	
66	    @Column(name = "postcode")
67	    private String postcode;
68	
69	    @Column(name = "registration_date")
70	    private LocalDate registrationDate;
71	
72	    @Column(name = "birth_date")
73	    private LocalDate birthDate;
74	
75	    @Column(name = "member_id")
76	    private String memberId;
77	
78	    @Column(name = "household_id")
79	    private String householdId;
80	
81	    @Column(name = "namesake_count")
82	    private Integer namesakeCount;
83	
84	    @Column(name = "bulk_signup_warning")
85	    private Boolean bulkSignupWarning;
86	
87	    @Column(name = "capacity_warning")
88	    private Boolean capacityWarning;
89	
90	    @Column(name = "household_size")
91	    private Integer householdSize;
92	
93	    @Column(name = "possible_duplicate")
94	    private Boolean possibleDuplicate;
95	
96	    @Column(name = "possible_duplicate_of")
97	    private Integer possibleDuplicateOf;
98	
99	    @Column(name = "membership_level_cap")
100	    private Integer membershipLevelCap;
101	
102	    @Column(name = "deleted", nullable = false)
103	    private Boolean deleted = false;
104	
105	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
106	    private Set<Pet> pets;
107	
108	    public String getTitle() {
109	        return this.title;
110	    }
111	
112	    public void setTitle(String title) {
113	        this.title = title;
114	    }
115	
116	    /**
117	     * The owner's salutation, composed from its {@link #getTitle() title} and
118	     * {@link #getLastName() last name}: {@code title + ' ' + lastName} when a title is
119	     * present, or just the last name when no title was supplied. Derived (not persisted);
120	     * recomputed each call. See {@link OwnerDerivations#salutation(String, String)}.
121	     *
122	     * @return the composed salutation
123	     */
124	    @Transient
125	    public String getSalutation() {
126	        return OwnerDerivations.salutation(this.title, this.getLastName());
127	    }
128	
129	    public String getAddress() {
130	        return this.address;
131	    }
132	
133	    public void setAddress(String address) {
134	        this.address = address;
135	    }
136	
137	    public String getAddressLine1() {
138	        return this.addressLine1;
139	    }
140	
141	    public void setAddressLine1(String addressLine1) {
142	        this.addressLine1 = addressLine1;
143	    }
144	
145	    public String getAddressLine2() {
146	        return this.addressLine2;
147	    }
148	
149	    public void setAddressLine2(String addressLine2) {
150	        this.addressLine2 = addressLine2;
151	    }
152	
153	    public String getCity() {
154	        return this.city;
155	    }
156	
157	    public void setCity(String city) {
158	        this.city = city;
159	    }
160	
161	    /**
162	     * The owner's locality, i.e. the canonical region it belongs to (read from the
163	     * assigned {@link #memberId} when present, otherwise derived from the owner's
164	     * own fields via {@link #regionForOwner()}). Derived (not persisted); recomputed
165	     * each call. See {@link OwnerDerivations#locality(String, String, String)} for the
166	     * full derivation.
167	     *
168	     * @return the canonical region string, or {@code "UNKNOWN"}
169	     */
170	    @Transient
171	    public String getLocality() {
172	        return OwnerDerivations.locality(this.memberId, this.postcode, this.city);
173	    }
174	
175	    /**
176	     * The canonical region derived for this owner from its own fields. Recomputed each
177	     * call. See {@link OwnerDerivations#region(String, String)} for the derivation.
178	     *
179	     * @return the canonical region string, or {@code "UNKNOWN"}
180	     */
181	    public String regionForOwner() {
182	        return OwnerDerivations.region(this.postcode, this.city);
183	    }
184	
185	    /**
186	     * The owner's IANA timezone name, derived from its {@link #getLocality() locality}
187	     * (canonical region) via the fixed region-to-timezone table. Derived (not persisted);
188	     * recomputed each call and {@code null} when the locality is not a known region. See
189	     * {@link OwnerDerivations#timezone(String)} for the derivation.
190	     *
191	     * @return the IANA timezone name, or {@code null}
192	     */
193	    @Transient
194	    public String getTimezone() {
195	        return OwnerDerivations.timezone(this.getLocality());
196	    }
197	
198	    /**
199	     * Whether this owner's postcode is consistent with its {@link #getLocality()
200	     * locality}: an absent postcode is accepted, a present one must be exactly four
201	     * digits and, when the locality has a known postcode range, fall within it. See
202	     * {@link OwnerDerivations#postcodeMatchesRegion(String, String)}.
203	     *
204	     * @return {@code true} if the postcode is absent or valid for the owner's locality
205	     */
206	    public boolean postcodeValidForLocality() {
207	        return OwnerDerivations.postcodeMatchesRegion(this.postcode, this.getLocality());
208	    }
209	
210	    /**
211	     * The owner's membership points, a non-negative score derived from its factors.
212	     * Derived (not persisted); recomputed from the current fields each call, so it rises
213	     * once the owner's tenure since {@link #registrationDate} exceeds 365 days. See
214	     * {@link OwnerDerivations#membershipPoints(String, Integer, Integer, LocalDate, LocalDate)}
215	     * for how it is scored.
216	     *
217	     * @return the membership points, 0 or more
218	     */
219	    @Transient
220	    public Integer getMembershipPoints() {
221	        return OwnerDerivations.membershipPoints(this.email, this.namesakeCount, this.householdSize,
222	            this.registrationDate, LocalDate.now());
223	    }
224	
225	    /**
226	     * The owner's membership level, a number from 1 to 4, mapped from its
227	     * {@link #getMembershipPoints() membership points}. Derived (not persisted);
228	     * recomputed from the current fields each call, so it rises to level 4 once the
229	     * owner's tenure since {@link #registrationDate} exceeds 365 days. The level is then
230	     * held to this owner's household level ceiling ({@link #getMembershipLevelCap()}): when
231	     * a ceiling was assigned at creation the reported level is at most that ceiling, one
232	     * above the highest level then held by an existing household member. See
233	     * {@link OwnerDerivations#membershipLevel(int, Integer)} for the mapping.
234	     *
235	     * @return the membership level, from 1 to 4
236	     */
237	    @Transient
238	    public Integer getMembershipLevel() {
239	        return OwnerDerivations.membershipLevel(getMembershipPoints(), this.membershipLevelCap);
240	    }
241	
242	    /**
243	     * The owner's marketing segment, formatted {@code <TIER>_<AREA>}, one of
244	     * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
245	     * {@code STANDARD_REGIONAL}: TIER is {@code PREMIUM} when its
246	     * {@link #getMembershipLevel() membership level} is 3 or more (otherwise
247	     * {@code STANDARD}) and AREA is {@code METRO} when its {@link #getLocality() locality}
248	     * is a known region (otherwise {@code REGIONAL}). Derived (not persisted); recomputed
249	     * each call. See {@link OwnerDerivations#ownerSegment(int, String)}.
250	     *
251	     * @return the owner's segment as {@code <TIER>_<AREA>}
252	     */
253	    @Transient
254	    public String getOwnerSegment() {
255	        return OwnerDerivations.ownerSegment(getMembershipLevel(), this.getLocality());
256	    }
257	
258	    /**
259	     * The owner's preferred contact channel, {@code "EMAIL"} or {@code "PHONE"}.
260	     * Derived (not persisted); recomputed from the current fields each call. See
261	     * {@link OwnerDerivations#contactPreference(String)}.
262	     *
263	     * @return {@code "EMAIL"} or {@code "PHONE"}
264	     */
265	    @Transient
266	    public String getContactPreference() {
267	        return OwnerDerivations.contactPreference(this.email);
268	    }
269	
270	    public String getTelephone() {
271	        return this.telephone;
272	    }
273	
274	    /**
275	     * The stored E.164 {@link #telephone} formatted for humans: a leading '+'
276	     * and country code, a space, then the national digits grouped in threes
277	     * (e.g. {@code "+61 412 345 678"}). Derived (not persisted); recomputed each
278	     * call and {@code null} when no telephone is present. See
279	     * {@link Telephones#toDisplay(String)} for the exact format.
280	     *
281	     * @return the human-formatted telephone, or {@code null} when absent
282	     */
283	    @Transient
284	    public String getTelephoneDisplay() {
285	        return Telephones.toDisplay(this.telephone);
286	    }
287	
288	    public void setTelephone(String telephone) {
289	        this.telephone = telephone;
290	    }
291	
292	    public String getEmail() {
293	        return this.email;
294	    }
295	
296	    public void setEmail(String email) {
297	        this.email = email;
298	    }
299	
300	    public String getPostcode() {
301	        return this.postcode;
302	    }
303	
304	    public void setPostcode(String postcode) {
305	        this.postcode = postcode;
306	    }
307	
308	    public LocalDate getRegistrationDate() {
309	        return this.registrationDate;
310	    }
311	
312	    public void setRegistrationDate(LocalDate registrationDate) {
313	        this.registrationDate = registrationDate;
314	    }
315	
316	    public LocalDate getBirthDate() {
317	        return this.birthDate;
318	    }
319	
320	    public void setBirthDate(LocalDate birthDate) {
321	        this.birthDate = birthDate;
322	    }
323	
324	    /**
325	     * The owner's age band, {@code "MINOR"}, {@code "ADULT"} or {@code "SENIOR"},
326	     * derived from {@link #birthDate} measured against {@link #registrationDate}.
327	     * Derived (not persisted); recomputed each call and {@code null} when no birth
328	     * date has been supplied. See
329	     * {@link OwnerDerivations#ageBand(LocalDate, LocalDate)} for the derivation.
330	     *
331	     * @return the age band, or {@code null} when no birth date is present
332	     */
333	    @Transient
334	    public String getAgeBand() {
335	        return OwnerDerivations.ageBand(this.birthDate, this.registrationDate);
336	    }
337	
338	    /**
339	     * The owner's fiscal year, formatted {@code FY<YY>}, derived from its
340	     * business-day-adjusted {@link #registrationDate} (the fiscal year starts on 1 July).
341	     * Derived (not persisted); recomputed each call and {@code null} when no registration
342	     * date is present. See {@link OwnerDerivations#fiscalYear(LocalDate)} for the derivation.
343	     *
344	     * @return the fiscal year as {@code FY<YY>}, or {@code null}
345	     */
346	    @Transient
347	    public String getFiscalYear() {
348	        return OwnerDerivations.fiscalYear(this.registrationDate);
349	    }
350	
351	    public String getMemberId() {
352	        return this.memberId;
353	    }
354	
355	    public void setMemberId(String memberId) {
356	        this.memberId = memberId;
357	    }
358	
359	    public String getHouseholdId() {
360	        return this.householdId;
361	    }
362	
363	    public void setHouseholdId(String householdId) {
364	        this.householdId = householdId;
365	    }
366	
367	    public Integer getNamesakeCount() {
368	        return this.namesakeCount;
369	    }
370	
371	    public void setNamesakeCount(Integer namesakeCount) {
372	        this.namesakeCount = namesakeCount;
373	    }
374	
375	    public Boolean getBulkSignupWarning() {
376	        return this.bulkSignupWarning;
377	    }
378	
379	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
380	        this.bulkSignupWarning = bulkSignupWarning;
381	    }
382	
383	    public Boolean getCapacityWarning() {
384	        return this.capacityWarning;
385	    }
386	
387	    public void setCapacityWarning(Boolean capacityWarning) {
388	        this.capacityWarning = capacityWarning;
389	    }
390	
391	    public Integer getHouseholdSize() {
392	        return this.householdSize;
393	    }
394	
395	    public void setHouseholdSize(Integer householdSize) {
396	        this.householdSize = householdSize;
397	    }
398	
399	    public Boolean getPossibleDuplicate() {
400	        return this.possibleDuplicate;
401	    }
402	
403	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
404	        this.possibleDuplicate = possibleDuplicate;
405	    }
406	
407	    public Integer getPossibleDuplicateOf() {
408	        return this.possibleDuplicateOf;
409	    }
410	
411	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
412	        this.possibleDuplicateOf = possibleDuplicateOf;
413	    }
414	
415	    /**
416	     * Whether this owner is flagged as risky: {@code true} when any of its risk signals
417	     * holds — it is a {@link #getPossibleDuplicate() possible duplicate}, its email domain
418	     * is disposable-adjacent (on the disposable-domain blocklist), or its city was over its
419	     * soft capacity at creation ({@link #getCapacityWarning() capacity warning}) — otherwise
420	     * {@code false}. Derived (not persisted); recomputed each call. See
421	     * {@link OwnerDerivations#riskFlag(Boolean, String, Boolean)}.
422	     *
423	     * @return {@code true} when any risk signal holds, otherwise {@code false}
424	     */
425	    @Transient
426	    public Boolean getRiskFlag() {
427	        return OwnerDerivations.riskFlag(this.possibleDuplicate, this.email, this.capacityWarning);
428	    }
429	
430	    /**
431	     * The household level ceiling assigned to this owner at creation: one above the highest
432	     * {@link #getMembershipLevel() membership level} then held by an existing member of its
433	     * household, or {@code null} when the owner joined no existing household (so no ceiling
434	     * applies). Persisted, and used by {@link #getMembershipLevel()} to cap the reported
435	     * level.
436	     *
437	     * @return the household level ceiling, or {@code null} when uncapped
438	     */
439	    public Integer getMembershipLevelCap() {
440	        return this.membershipLevelCap;
441	    }
442	
443	    public void setMembershipLevelCap(Integer membershipLevelCap) {
444	        this.membershipLevelCap = membershipLevelCap;
445	    }
446	
447	    public Boolean getDeleted() {
448	        return this.deleted;
449	    }
450	
451	    public void setDeleted(Boolean deleted) {
452	        this.deleted = deleted;
453	    }
454	
455	    /**
456	     * The derived key used for duplicate detection: the SHA-256 hex digest over this
457	     * owner's normalised telephone, lower-cased email and the {@link #soundex(String)
458	     * Soundex} of its last name. Two owners are duplicates exactly when their whole
459	     * identity keys are equal, so because the telephone is part of the key, members of
460	     * the same household with different telephones have different keys. Derived (not
461	     * persisted); recomputed each call. See
462	     * {@link OwnerDerivations#identityKey(String, String, String)} for the exact format.
463	     *
464	     * @return the owner's identity key
465	     */
466	    @Transient
467	    public String getIdentityKey() {
468	        return OwnerDerivations.identityKey(this.telephone, this.email, this.getLastName());
469	    }
470	
471	    /**
472	     * The American Soundex code of the given name. This is the last-name comparison used
473	     * by both the identity key and the soft-match duplicate check; see
474	     * {@link OwnerDerivations#soundex(String)} for the exact algorithm.
475	     *
476	     * @param value the name to encode (may be {@code null})
477	     * @return the four-character Soundex code, or the empty string
478	     */
479	    public static String soundex(String value) {
480	        return OwnerDerivations.soundex(value);
481	    }
482	
483	    /**
484	     * Compute the unified member id to assign to this owner at creation, formatted
485	     * {@code <REGION><FY><HASH8><CHK>} from the owner's (already normalised) fields and
486	     * registration date. This is the value stored in {@link #getMemberId()}; see
487	     * {@link OwnerDerivations#memberId(String, String, String, LocalDate)} for the exact
488	     * format.
489	     *
490	     * @return the member id to assign
491	     */
492	    public String computeMemberId() {
493	        return OwnerDerivations.memberId(regionForOwner(), this.telephone, this.getLastName(),
494	            this.registrationDate);
495	    }
496	
497	    /**
498	     * Compute the stable household identifier for this owner, derived deterministically
499	     * from its last name and postcode so every owner sharing a last name and postcode
500	     * resolves to the same value. This is the value stored in {@link #getHouseholdId()};
501	     * see {@link OwnerDerivations#householdId(String, String)} for the exact derivation.
502	     *
503	     * @return the household identifier
504	     */
505	    public String computeHouseholdId() {
506	        return OwnerDerivations.householdId(normalize(this.getLastName()), this.postcode);
507	    }
508	
509	    /**
510	     * Whether this owner belongs to the same household as {@code other}: that is, they
511	     * share the same last name and postcode. The last name is compared
512	     * case-insensitively with runs of whitespace collapsed to a single space (and
513	     * surrounding whitespace trimmed); the postcode is compared for exact equality (two
514	     * absent postcodes count as equal). Owners in the same household resolve to the same
515	     * {@link #computeHouseholdId() household identifier}.
516	     *
517	     * @param other the owner to compare against
518	     * @return {@code true} if both owners share a household
519	     */
520	    public boolean sameHouseholdAs(Owner other) {
521	        return normalize(this.getLastName()).equals(normalize(other.getLastName()))
522	            && Objects.equals(this.postcode, other.postcode);
523	    }
524	
525	    /**
526	     * Normalise a value for case-insensitive, whitespace-insensitive comparison:
527	     * trim, collapse internal runs of whitespace to a single space and lower-case.
528	     */
529	    private static String normalize(String value) {
530	        return OwnerDerivations.collapseWhitespace(value).toLowerCase();
531	    }
532	
533	    /**
534	     * Reduce an address to its canonical stored form. This is the value stored,
535	     * returned and used for every household comparison; see
536	     * {@link OwnerDerivations#normalizeAddress(String)} for the exact normalisation.
537	     *
538	     * @param value the raw address (may be {@code null})
539	     * @return the normalised address, or the empty string if {@code value} is
540	     *         {@code null} or blank
541	     */
542	    public static String normalizeAddress(String value) {
543	        return OwnerDerivations.normalizeAddress(value);
544	    }
545	
546	    /**
547	     * Whether the given (already lower-cased) email address belongs to a disposable,
548	     * throw-away mailbox domain on the blocklist. This is the disposable-domain check
549	     * applied at creation to reject such addresses; see
550	     * {@link OwnerDerivations#emailDomainIsDisposable(String)} for the exact rule.
551	     *
552	     * @param email the owner's normalised (lower-cased) email address
553	     * @return {@code true} if the email's domain is on the disposable-domain blocklist
554	     */
555	    public static boolean emailDomainIsDisposable(String email) {
556	        return OwnerDerivations.emailDomainIsDisposable(email);
557	    }
558	
559	    protected Set<Pet> getPetsInternal() {
560	        if (this.pets == null) {
561	            this.pets = new HashSet<>();
562	        }
563	        return this.pets;
564	    }
565	
566	    protected void setPetsInternal(Set<Pet> pets) {
567	        this.pets = pets;
568	    }
569	
570	    public List<Pet> getPets() {
571	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
572	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
573	        return Collections.unmodifiableList(sortedPets);
574	    }
575	
576	    public void setPets(List<Pet> pets) {
577	        this.pets = new HashSet<>(pets);
578	    }
579	
580	    public void addPet(Pet pet) {
581	        getPetsInternal().add(pet);
582	        pet.setOwner(this);
583	    }
584	
585	    /**
586	     * Return the Pet with the given name, or null if none found for this Owner.
587	     *
588	     * @param name to test
589	     * @return true if pet name is already in use
590	     */
591	    public Pet getPet(String name) {
592	        return getPet(name, false);
593	    }
594	
595	    /**
596	     * Return the Pet with the given name, or null if none found for this Owner.
597	     *
598	     * @param name to test
599	     * @return true if pet name is already in use
600	     */
601	    public Pet getPet(String name, boolean ignoreNew) {
602	        name = name.toLowerCase();
603	        for (Pet pet : getPetsInternal()) {
604	            if (!ignoreNew || !pet.isNew()) {
605	                String compName = pet.getName();
606	                compName = compName.toLowerCase();
607	                if (compName.equals(name)) {
608	                    return pet;
609	                }
610	            }
611	        }
612	        return null;
613	    }
614	
615	    public Pet getPet(Integer petId) {
616	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
617	    }
618	
619	    @Override
620	    public String toString() {
621	        return new ToStringCreator(this)
622	
623	            .append("id", this.getId())
624	            .append("new", this.isNew())
625	            .append("lastName", this.getLastName())
626	            .append("firstName", this.getFirstName())
627	            .append("address", this.address)
628	            .append("city", this.city)
629	            .append("telephone", this.telephone)
630	            .toString();
631	    }
632	}
