16	package org.springframework.samples.petclinic.model;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	import java.time.LocalDate;
22	import java.time.Month;
23	import java.time.Period;
24	import java.util.Map;
25	import java.util.Set;
26	
27	/**
28	 * Pure derivations of an {@link Owner}'s read-only attributes.
29	 *
30	 * <p>Each method computes one derived value from an owner's own field values and
31	 * nothing else, so the computations stay stateless and side-effect free. {@link Owner}
32	 * exposes these through thin {@code @Transient} getters that pass in the relevant
33	 * fields; keeping the arithmetic here rather than on the entity leaves {@code Owner}
34	 * to describe its persistent state and relationships while its growing family of
35	 * derived attributes lives together in one place.
36	 */
37	final class OwnerDerivations {
38	
39	    /** Fixed city-to-region table used to derive {@link #region}. */
40	    private static final Map<String, String> CITY_REGION = Map.of(
41	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
42	
43	    /** Region -> inclusive 4-digit postcode range {low, high} used to derive
44	     *  {@link #region} in preference to the city. */
45	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
46	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
47	
48	    /** Fixed region-to-timezone table (IANA names) used to derive {@link #timezone}. */
49	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
50	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
51	
52	    /** Email domains that identify disposable, throw-away mailboxes, used to derive
53	     *  {@link #emailDomainIsDisposable(String)}. */
54	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
55	        "mailinator.com", "tempmail.com", "guerrillamail.com");
56	
57	    private OwnerDerivations() {
58	    }
59	
60	    /**
61	     * The owner's locality, i.e. the canonical region it belongs to. This is read
62	     * from the unified {@code memberId} identity: the region is the leading
63	     * {@code <REGION>} component of the assigned member id, i.e. the run of letters
64	     * before its two-digit fiscal-year segment (e.g. {@code NSW} for
65	     * {@code NSW279F86D0817}). Until an owner has been assigned a member id (for example
66	     * while its create request is still being validated) this falls back to the region
67	     * derived directly from its own fields (see {@link #region(String, String)}).
68	     *
69	     * @return the canonical region string, or {@code "UNKNOWN"}
70	     */
71	    static String locality(String memberId, String postcode, String city) {
72	        String assigned = memberIdRegion(memberId);
73	        if (assigned != null) {
74	            return assigned;
75	        }
76	        return region(postcode, city);
77	    }
78	
79	    /**
80	     * The region component encoded in an assigned {@code memberId}: its leading
81	     * {@code <REGION>} run of letters, which precedes the two-digit fiscal-year segment
82	     * (e.g. {@code NSW} for {@code NSW279F86D0817}), or {@code null} when no member id has
83	     * been assigned yet or it carries no leading region component. Reading the region back
84	     * out of the identifier lives here so {@link #locality(String, String, String)} stays a
85	     * thin read-then-fall-back and the one place that knows the identifier's shape is
86	     * isolated.
87	     *
88	     * @return the encoded region, or {@code null}
89	     */
90	    private static String memberIdRegion(String memberId) {
91	        if (memberId == null) {
92	            return null;
93	        }
94	        int i = 0;
95	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
96	            i++;
97	        }
98	        return i > 0 ? memberId.substring(0, i) : null;
99	    }
100	
101	    /**
102	     * The canonical region derived for an owner from its own fields. The postcode is
103	     * consulted first: when it is present and falls within a known region's inclusive
104	     * 4-digit range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD
105	     * 4000-4099}) that region is returned. Only when the postcode is absent or in no
106	     * known range does this fall back to the fixed city-to-region table
107	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}),
108	     * returning {@code "UNKNOWN"} when the city is not in the table either. This yields
109	     * the same region for the known cities while disambiguating cities that share a name
110	     * via their postcode.
111	     *
112	     * @return the canonical region string, or {@code "UNKNOWN"}
113	     */
114	    static String region(String postcode, String city) {
115	        String byPostcode = regionForPostcode(postcode);
116	        if (byPostcode != null) {
117	            return byPostcode;
118	        }
119	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
120	    }
121	
122	    /**
123	     * The IANA timezone name derived from the given {@code locality} (a canonical
124	     * region) via the fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
125	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). Returns
126	     * {@code null} when the locality is not one of the known regions (for example
127	     * {@code "UNKNOWN"}).
128	     *
129	     * @return the IANA timezone name, or {@code null}
130	     */
131	    static String timezone(String locality) {
132	        return REGION_TIMEZONE.get(locality);
133	    }
134	
135	    /**
136	     * The region whose inclusive postcode range contains the given postcode, or
137	     * {@code null} when the postcode is absent, not a four-digit number, or in no
138	     * known range.
139	     */
140	    private static String regionForPostcode(String postcode) {
141	        if (postcode == null || !postcode.matches("\\d{4}")) {
142	            return null;
143	        }
144	        int value = Integer.parseInt(postcode);
145	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
146	            int[] range = entry.getValue();
147	            if (value >= range[0] && value <= range[1]) {
148	                return entry.getKey();
149	            }
150	        }
151	        return null;
152	    }
153	
154	    /**
155	     * Whether the given {@code postcode} is acceptable for the given {@code region}: an
156	     * absent postcode is always accepted, a present postcode must be exactly four
157	     * digits and, when the region has a known inclusive postcode range
158	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), fall within
159	     * it. A region with no known range (for example {@code "UNKNOWN"}) accepts any
160	     * four-digit postcode.
161	     *
162	     * @return {@code true} if the postcode is absent or valid for the region
163	     */
164	    static boolean postcodeMatchesRegion(String postcode, String region) {
165	        if (postcode == null) {
166	            return true;
167	        }
168	        if (!postcode.matches("\\d{4}")) {
169	            return false;
170	        }
171	        int[] range = REGION_POSTCODES.get(region);
172	        if (range == null) {
173	            return true;
174	        }
175	        int value = Integer.parseInt(postcode);
176	        return value >= range[0] && value <= range[1];
177	    }
178	
179	    /**
180	     * The owner's membership points, a non-negative score derived from its factors:
181	     * starting at 0, add 2 when an {@code email} is present, add 1 when
182	     * {@code namesakeCount} is 0, add 2 for a household of 3 or more (its
183	     * {@code householdSize}) and add 3 when the owner's tenure exceeds a year, measured as
184	     * the number of whole fiscal years elapsed from its {@code registrationDate} up to
185	     * {@code asOf} (the fiscal year starts on 1 July). Because a newly created owner has
186	     * zero elapsed fiscal years, it never earns the tenure points at creation.
187	     *
188	     * @return the membership points, 0 or more
189	     */
190	    static int membershipPoints(String email, Integer namesakeCount, Integer householdSize,
191	            LocalDate registrationDate, LocalDate asOf) {
192	        int points = 0;
193	        if (hasEmail(email)) {
194	            points += 2;
195	        }
196	        if (namesakeCount != null && namesakeCount == 0) {
197	            points += 1;
198	        }
199	        if (householdSize != null && householdSize >= 3) {
200	            points += 2;
201	        }
202	        if (tenureExceedsYear(registrationDate, asOf)) {
203	            points += 3;
204	        }
205	        return points;
206	    }
207	
208	    /**
209	     * The owner's membership level, a number from 1 to 4, mapped from its
210	     * {@link #membershipPoints(String, Integer, Integer, LocalDate, LocalDate) membership
211	     * points}: level 1 for 0-1 points, level 2 for 2-3, level 3 for 4-5 and level 4 for 6
212	     * or more.
213	     *
214	     * @return the membership level, from 1 to 4
215	     */
216	    static int membershipLevel(int points) {
217	        if (points <= 1) {
218	            return 1;
219	        }
220	        if (points <= 3) {
221	            return 2;
222	        }
223	        if (points <= 5) {
224	            return 3;
225	        }
226	        return 4;
227	    }
228	
229	    /**
230	     * The owner's membership level after applying its household level ceiling. The level
231	     * mapped from {@code points} (see {@link #membershipLevel(int)}) is returned unchanged
232	     * when {@code cap} is {@code null} (the owner joined no existing household), and
233	     * otherwise capped to at most {@code cap} — the ceiling assigned at creation, one above
234	     * the highest level then held by an existing household member — so a new owner can rise
235	     * to at most one level above its household.
236	     *
237	     * @return the capped membership level, from 1 to 4
238	     */
239	    static int membershipLevel(int points, Integer cap) {
240	        int level = membershipLevel(points);
241	        return cap == null ? level : Math.min(level, cap);
242	    }
243	
244	    /**
245	     * The owner's marketing segment, formatted {@code <TIER>_<AREA>}, one of
246	     * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
247	     * {@code STANDARD_REGIONAL}. TIER is {@code PREMIUM} when {@code membershipLevel} is 3
248	     * or more, otherwise {@code STANDARD}. AREA is {@code METRO} when {@code locality} is a
249	     * known region ({@code NSW}, {@code VIC} or {@code QLD}), otherwise {@code REGIONAL}.
250	     *
251	     * @return the owner's segment as {@code <TIER>_<AREA>}
252	     */
253	    static String ownerSegment(int membershipLevel, String locality) {
254	        String tier = membershipLevel >= 3 ? "PREMIUM" : "STANDARD";
255	        String area = REGION_TIMEZONE.containsKey(locality) ? "METRO" : "REGIONAL";
256	        return tier + "_" + area;
257	    }
258	
259	    /**
260	     * Whether the owner's tenure exceeds a year, i.e. at least one whole fiscal year has
261	     * elapsed from its {@code registrationDate} up to {@code asOf} (see
262	     * {@link #elapsedFiscalYears(LocalDate, LocalDate)}). This is the single tenure test
263	     * the tenure-driven membership derivations share, so they agree on exactly when an
264	     * owner has been a member for "over a year"; it is {@code false} whenever either date
265	     * is absent.
266	     */
267	    private static boolean tenureExceedsYear(LocalDate registrationDate, LocalDate asOf) {
268	        return registrationDate != null && asOf != null
269	            && elapsedFiscalYears(registrationDate, asOf) >= 1;
270	    }
271	
272	    /**
273	     * The number of whole fiscal years elapsed from {@code registrationDate} up to
274	     * {@code asOf}, i.e. the difference between the fiscal year that contains {@code asOf}
275	     * and the one that contains {@code registrationDate} (see {@link #fiscalYearOf(LocalDate)}).
276	     * Two dates in the same fiscal year yield {@code 0}, so an owner registered in the
277	     * current fiscal year has zero tenure until the next 1 July rollover.
278	     */
279	    static int elapsedFiscalYears(LocalDate registrationDate, LocalDate asOf) {
280	        return fiscalYearOf(asOf) - fiscalYearOf(registrationDate);
281	    }
282	
283	    /**
284	     * The fiscal year that contains the given date, as a four-digit calendar year. The
285	     * fiscal year runs from 1 July to 30 June and is labelled by the calendar year in
286	     * which it ends: a date from January to June falls in the fiscal year of its own
287	     * calendar year, while a date from July to December falls in the next calendar year's
288	     * fiscal year (e.g. {@code 2026-05-03 -> 2026} but {@code 2026-08-03 -> 2027}).
289	     */
290	    static int fiscalYearOf(LocalDate date) {
291	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
292	    }
293	
294	    /**
295	     * The owner's fiscal year, formatted {@code FY<YY>} where YY is the last two digits of
296	     * the fiscal year (see {@link #fiscalYearOf(LocalDate)}) that contains its
297	     * business-day-adjusted {@code registrationDate}, e.g. {@code FY27} for a registration
298	     * date of {@code 2026-08-03}. Returns {@code null} when no registration date is present.
299	     *
300	     * @return the fiscal year as {@code FY<YY>}, or {@code null}
301	     */
302	    static String fiscalYear(LocalDate registrationDate) {
303	        if (registrationDate == null) {
304	            return null;
305	        }
306	        return "FY" + fiscalYearSegment(registrationDate);
307	    }
308	
309	    /**
310	     * The two-digit fiscal-year segment for a registration date: the last two digits of the
311	     * fiscal year that contains it (see {@link #fiscalYearOf(LocalDate)}), zero-padded, e.g.
312	     * {@code "27"} for a registration date of {@code 2026-08-03}. This is the single
313	     * definition the fiscal-year-bearing identifiers share, so they agree on exactly which
314	     * two-digit year they carry.
315	     *
316	     * @return the two-digit fiscal-year segment
317	     */
318	    static String fiscalYearSegment(LocalDate registrationDate) {
319	        return String.format("%02d", fiscalYearOf(registrationDate) % 100);
320	    }
321	
322	    /**
323	     * The owner's salutation, formed as {@code title + ' ' + lastName} when a
324	     * {@code title} is present, or just the {@code lastName} when no title is supplied.
325	     * A {@code null} or blank title contributes nothing, yielding the bare last name.
326	     *
327	     * @return the composed salutation
328	     */
329	    static String salutation(String title, String lastName) {
330	        if (title == null || title.isBlank()) {
331	            return lastName;
332	        }
333	        return title + " " + lastName;
334	    }
335	
336	    /**
337	     * The owner's preferred contact channel: {@code "EMAIL"} when an {@code email}
338	     * is present, otherwise {@code "PHONE"}.
339	     *
340	     * @return {@code "EMAIL"} or {@code "PHONE"}
341	     */
342	    static String contactPreference(String email) {
343	        if (hasEmail(email)) {
344	            return "EMAIL";
345	        }
346	        return "PHONE";
347	    }
348	
349	    /**
350	     * Whether the owner has an email address on file, i.e. its {@code email} is present
351	     * and not blank. This is the single presence test the email-driven derivations share
352	     * (a membership-level factor and the {@link #contactPreference(String) contact
353	     * preference}), so they agree on exactly what counts as "has an email".
354	     */
355	    private static boolean hasEmail(String email) {
356	        return email != null && !email.isBlank();
357	    }
358	
359	    /**
360	     * The domain component of an email address: the lower-cased run after its final
361	     * {@code '@'}, or the empty string when the value is absent or carries no {@code '@'}.
362	     * This is the single domain extraction the email-domain derivations share, so they
363	     * agree on exactly what an address's domain is; each then classifies that domain in
364	     * its own way.
365	     *
366	     * @return the lower-cased email domain, or the empty string when there is none
367	     */
368	    static String emailDomain(String email) {
369	        if (email == null) {
370	            return "";
371	        }
372	        int at = email.lastIndexOf('@');
373	        if (at < 0) {
374	            return "";
375	        }
376	        return email.substring(at + 1).toLowerCase();
377	    }
378	
379	    /**
380	     * Whether the email's {@link #emailDomain(String) domain} is one of the known
381	     * disposable, throw-away mailbox domains ({@code mailinator.com}, {@code tempmail.com},
382	     * {@code guerrillamail.com}). An address without a domain (absent, or carrying no
383	     * {@code '@'}) is treated as having no disposable domain.
384	     *
385	     * @return {@code true} if the email's domain is on the disposable-domain blocklist
386	     */
387	    static boolean emailDomainIsDisposable(String email) {
388	        return DISPOSABLE_EMAIL_DOMAINS.contains(emailDomain(email));
389	    }
390	
391	    /**
392	     * Whether the owner should be flagged as risky, i.e. any one of its risk signals
393	     * holds: it is a possible duplicate ({@code possibleDuplicate}), its email domain is
394	     * disposable-adjacent (on the disposable-domain blocklist, see
395	     * {@link #emailDomainIsDisposable(String)}), or its city was over its soft capacity at
396	     * creation ({@code capacityWarning}). The two persisted flags are treated as
397	     * {@code false} when absent, so the risk flag is {@code false} for an owner with no
398	     * signal set.
399	     *
400	     * @return {@code true} when any risk signal holds, otherwise {@code false}
401	     */
402	    static boolean riskFlag(Boolean possibleDuplicate, String email, Boolean capacityWarning) {
403	        return Boolean.TRUE.equals(possibleDuplicate)
404	            || emailDomainIsDisposable(email)
405	            || Boolean.TRUE.equals(capacityWarning);
406	    }
407	
408	    /**
409	     * The Luhn check digit (0-9) computed over the decimal digits contained in the
410	     * given {@code value}, processed right-to-left with every second digit doubled (and
411	     * reduced by 9 when the double exceeds 9). Non-digit characters are ignored, and an
412	     * absent or digit-free value yields {@code 0}.
413	     *
414	     * @return the Luhn check digit, from 0 to 9
415	     */
416	    static int checkDigit(String value) {
417	        int sum = 0;
418	        boolean doubleDigit = true;
419	        for (int i = (value == null ? 0 : value.length()) - 1; i >= 0; i--) {
420	            char c = value.charAt(i);
421	            if (c < '0' || c > '9') {
422	                continue;
423	            }
424	            int d = c - '0';
425	            if (doubleDigit) {
426	                d *= 2;
427	                if (d > 9) {
428	                    d -= 9;
429	                }
430	            }
431	            sum += d;
432	            doubleDigit = !doubleDigit;
433	        }
434	        return (10 - (sum % 10)) % 10;
435	    }
436	
437	    /**
438	     * The owner's age band, derived from its {@code birthDate} measured against its
439	     * {@code registrationDate}: {@code "MINOR"} when the owner is under 18 on the
440	     * registration date, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or
441	     * over. The age is the number of whole years between the two dates. Returns
442	     * {@code null} when either date is absent, so no band is reported for an owner
443	     * without a supplied birth date.
444	     *
445	     * @return {@code "MINOR"}, {@code "ADULT"}, {@code "SENIOR"}, or {@code null}
446	     */
447	    static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
448	        if (birthDate == null || registrationDate == null) {
449	            return null;
450	        }
451	        int age = Period.between(birthDate, registrationDate).getYears();
452	        if (age < 18) {
453	            return "MINOR";
454	        }
455	        if (age < 65) {
456	            return "ADULT";
457	        }
458	        return "SENIOR";
459	    }
460	
461	    /**
462	     * The single derived key used for duplicate detection: the lower-case hexadecimal
463	     * SHA-256 digest of {@code normalizedTelephone + '|' + lowerEmail + '|' +
464	     * soundex(lastName)}. The telephone is the owner's stored (E.164-normalised)
465	     * telephone (or the empty string when absent), the email is the stored (lower-cased)
466	     * email or the empty string when absent, and the last-name component is the
467	     * {@link #soundex(String) Soundex code} of the owner's last name. Because the
468	     * telephone is part of the key, two owners sharing a last name and postcode but with
469	     * different telephones have different keys.
470	     *
471	     * @return the owner's identity key, a 64-character lower-case hex string
472	     */
473	    static String identityKey(String telephone, String email, String lastName) {
474	        String tel = telephone == null ? "" : telephone;
475	        String mail = email == null ? "" : email.toLowerCase();
476	        return sha256Hex(tel + "|" + mail + "|" + soundex(lastName));
477	    }
478	
479	    /**
480	     * The American Soundex code of the given name: its first letter followed by three
481	     * digits derived from the remaining consonants ({@code b,f,p,v -> 1};
482	     * {@code c,g,j,k,q,s,x,z -> 2}; {@code d,t -> 3}; {@code l -> 4}; {@code m,n -> 5};
483	     * {@code r -> 6}), where adjacent letters mapping to the same digit (including when
484	     * separated only by {@code h} or {@code w}) are coded once, vowels ({@code a,e,i,o,u},
485	     * and {@code y}) separate otherwise-identical digits, and the result is zero-padded or
486	     * truncated to exactly four characters. Non-letters are ignored; an absent or
487	     * letter-free value yields the empty string.
488	     *
489	     * @param value the name to encode (may be {@code null})
490	     * @return the four-character Soundex code, or the empty string
491	     */
492	    static String soundex(String value) {
493	        if (value == null) {
494	            return "";
495	        }
496	        StringBuilder letters = new StringBuilder();
497	        for (char c : value.toUpperCase().toCharArray()) {
498	            if (c >= 'A' && c <= 'Z') {
499	                letters.append(c);
500	            }
501	        }
502	        if (letters.length() == 0) {
503	            return "";
504	        }
505	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
506	        char previousDigit = soundexDigit(letters.charAt(0));
507	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
508	            char letter = letters.charAt(i);
509	            char digit = soundexDigit(letter);
510	            if (digit != '0' && digit != previousDigit) {
511	                code.append(digit);
512	            }
513	            if (letter != 'H' && letter != 'W') {
514	                previousDigit = digit;
515	            }
516	        }
517	        while (code.length() < 4) {
518	            code.append('0');
519	        }
520	        return code.toString();
521	    }
522	
523	    /**
524	     * The Soundex digit for a single upper-case letter, or {@code '0'} for a letter that
525	     * carries no Soundex digit (the vowels {@code a,e,i,o,u}, and {@code y,h,w}).
526	     */
527	    private static char soundexDigit(char c) {
528	        return switch (c) {
529	            case 'B', 'F', 'P', 'V' -> '1';
530	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
531	            case 'D', 'T' -> '3';
532	            case 'L' -> '4';
533	            case 'M', 'N' -> '5';
534	            case 'R' -> '6';
535	            default -> '0';
536	        };
537	    }
538	
539	    /**
540	     * The owner's unified member id, formatted {@code <REGION><FY><HASH8><CHK>}: {@code region}
541	     * is the owner's canonical region (see {@link #region(String, String)}), FY is the
542	     * two-digit {@link #fiscalYearSegment(LocalDate) fiscal-year segment} of its
543	     * {@code registrationDate}, HASH8 is the {@link #hash8(String, String) HASH8} of its
544	     * telephone and last name, and CHK is a single {@link #checkDigit(String) Luhn check
545	     * digit} computed over the decimal digits of {@code <REGION><FY><HASH8>}
546	     * (e.g. {@code NSW279F86D0817}). This unifies the former customer code and membership
547	     * number into one identifier.
548	     *
549	     * @return the member id
550	     */
551	    static String memberId(String region, String telephone, String lastName,
552	            LocalDate registrationDate) {
553	        String base = region + fiscalYearSegment(registrationDate) + hash8(telephone, lastName);
554	        return base + checkDigit(base);
555	    }
556	
557	    /**
558	     * The HASH8 component of the region-and-hash identity: the first eight upper-case
559	     * hexadecimal characters of the SHA-256 digest of the owner's normalised
560	     * {@code telephone} concatenated with its {@code lastName} (e.g. {@code 9F86D081}).
561	     * Held as its own derivation so the identity's hash component has a single definition
562	     * rather than being spelled out at each identifier that embeds it.
563	     *
564	     * @return the eight upper-case hexadecimal HASH8 characters
565	     */
566	    static String hash8(String telephone, String lastName) {
567	        return sha256Hex(telephone + lastName).substring(0, 8).toUpperCase();
568	    }
569	
570	    /**
571	     * The stable identifier for the household an owner belongs to, derived
572	     * deterministically from its {@code normalizedLastName} and {@code postcode} so that
573	     * every owner sharing a last name and postcode resolves to the same value. It is the
574	     * first twelve lower-case hexadecimal characters of the SHA-256 digest of
575	     * {@code normalizedLastName + '|' + postcode} (an absent postcode contributes the
576	     * empty string).
577	     *
578	     * @return the household identifier
579	     */
580	    static String householdId(String normalizedLastName, String postcode) {
581	        String pc = postcode == null ? "" : postcode;
582	        return sha256Hex(normalizedLastName + "|" + pc).substring(0, 12);
583	    }
584	
585	    /**
586	     * Reduce an address to its canonical stored form: trim and collapse runs of
587	     * whitespace to a single space, upper-case, and expand common abbreviations
588	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}) whenever
589	     * they appear as whole words. The result is what is stored, returned and used
590	     * for every household comparison; it is idempotent, so re-normalising an
591	     * already-normalised address leaves it unchanged.
592	     *
593	     * @param value the raw address (may be {@code null})
594	     * @return the normalised address, or the empty string if {@code value} is
595	     *         {@code null} or blank
596	     */
597	    static String normalizeAddress(String value) {
598	        String collapsed = collapseWhitespace(value).toUpperCase();
599	        if (collapsed.isEmpty()) {
600	            return "";
601	        }
602	        String[] tokens = collapsed.split(" ");
603	        for (int i = 0; i < tokens.length; i++) {
604	            tokens[i] = switch (tokens[i]) {
605	                case "ST" -> "STREET";
606	                case "RD" -> "ROAD";
607	                case "AVE" -> "AVENUE";
608	                default -> tokens[i];
609	            };
610	        }
611	        return String.join(" ", tokens);
612	    }
613	
614	    /**
615	     * Trim the given value and collapse every internal run of whitespace to a single
616	     * space, treating an absent value as empty. This is the single whitespace
617	     * normalisation the name and address normalisers share, so they agree on what
618	     * counts as insignificant whitespace; each then applies its own casing (and, for
619	     * addresses, whole-word abbreviation expansion).
620	     *
621	     * @param value the raw value (may be {@code null})
622	     * @return the trimmed, whitespace-collapsed value, or the empty string when
623	     *         {@code value} is {@code null}
624	     */
625	    static String collapseWhitespace(String value) {
626	        if (value == null) {
627	            return "";
628	        }
629	        return value.trim().replaceAll("\\s+", " ");
630	    }
631	
632	    /**
633	     * The SHA-256 digest of the UTF-8 bytes of the given value, as a lower-case
634	     * hexadecimal string. Callers take the prefix and case they need.
635	     */
636	    static String sha256Hex(String value) {
637	        try {
638	            byte[] digest = MessageDigest.getInstance("SHA-256")
639	                .digest(value.getBytes(StandardCharsets.UTF_8));
640	            StringBuilder hex = new StringBuilder(digest.length * 2);
641	            for (byte b : digest) {
642	                hex.append(String.format("%02x", b));
643	            }
644	            return hex.toString();
645	        } catch (NoSuchAlgorithmException e) {
646	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
647	        }
648	    }
649	}
