106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
109	        Owner owner = this.clinicService.findOwnerById(ownerId);
110	        if (owner == null) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
114	    }
115	
116	    /**
117	     * Remembers, per already-seen {@code Idempotency-Key}, the id of the owner that key
118	     * originally created, so a retried create with the same key returns that owner instead
119	     * of creating a duplicate. Held in memory for the application's lifetime and keyed by the
120	     * raw header value.
121	     */
122	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
123	
124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
127	        boolean hasKey = idempotencyKey != null && !idempotencyKey.isBlank();
128	        if (hasKey) {
129	            Integer existingId = idempotentCreates.get(idempotencyKey);
130	            if (existingId != null) {
131	                Owner existing = this.clinicService.findOwnerById(existingId);
132	                if (existing != null) {
133	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
134	                }
135	            }
136	        }
137	        ResponseEntity<OwnerDto> response = createNewOwner(ownerFieldsDto);
138	        if (hasKey && response.getStatusCode() == HttpStatus.CREATED
139	            && response.getBody() != null && response.getBody().getId() != null) {
140	            idempotentCreates.putIfAbsent(idempotencyKey, response.getBody().getId());
141	        }
142	        return response;
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
148	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
149	        if (currentOwner == null) {
150	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
151	        }
152	        currentOwner.setAddress(ownerFieldsDto.getAddress());
153	        currentOwner.setCity(ownerFieldsDto.getCity());
154	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
155	        currentOwner.setLastName(ownerFieldsDto.getLastName());
156	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
157	        String email = ownerFieldsDto.getEmail();
158	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
159	        this.clinicService.saveOwner(currentOwner);
160	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
161	    }
