239	    }
240	
241	    /**
242	     * Create and persist a brand-new owner from the supplied fields, returning the
243	     * {@code 201 Created} response for it. This gathers the whole create pipeline in one
244	     * place — map the fields, {@link #normalizeNewOwner normalise} them, apply the daily
245	     * and city gates (each with its own rejection status), resolve any household,
246	     * {@link #assignDerivedAttributes derive the create-time attributes} (including the
247	     * household level ceiling that caps the owner's membership level), save, audit and
248	     * build the response with its {@code Location} header — so {@link #addOwner} itself
249	     * stays a thin entry point. An owner joining an existing household is admitted (its
250	     * membership level is capped to one above the household maximum rather than rejected):
251	     * two owners sharing a last name and postcode but with different telephones are no
252	     * longer a hard duplicate but a soft match. Duplicate detection is the single
253	     * {@link Owner#getIdentityKey() identity key}: a create whose identity key matches an
254	     * existing, non-deleted owner is rejected with {@code 409 Conflict}.
255	     *
256	     * @param ownerFieldsDto the owner fields from the request body
257	     * @return {@code 201 Created} with the created owner and its {@code Location} header
258	     * @throws RejectedRequestException with the appropriate rejection status:
259	     *         {@code 400 Bad Request} when the fields are invalid, {@code 429 Too Many
260	     *         Requests} when the day's create cap is reached, or {@code 409 Conflict} when
261	     *         the city is at capacity or the owner's identity key duplicates an existing
262	     *         owner
263	     */
264	    private ResponseEntity<OwnerDto> createNewOwner(OwnerFieldsDto ownerFieldsDto) {
265	        HttpHeaders headers = new HttpHeaders();
266	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
267	        if (!normalizeNewOwner(owner)) {
268	            throw new RejectedRequestException(HttpStatus.BAD_REQUEST);
269	        }
270	        if (dailyLimitReached(owner.getRegistrationDate())) {
271	            throw new RejectedRequestException(HttpStatus.TOO_MANY_REQUESTS);
272	        }
273	        if (cityIsAtCapacity(owner.getCity())) {
274	            throw new RejectedRequestException(HttpStatus.CONFLICT);
275	        }
276	        owner.setHouseholdId(owner.computeHouseholdId());
277	        if (isDuplicateIdentity(owner)) {
278	            throw new RejectedRequestException(HttpStatus.CONFLICT);
279	        }
280	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
281	        List<Owner> householdMembers = findHouseholdMembers(owner);
282	        boolean joinsExistingHousehold = !householdMembers.isEmpty();
283	        boolean declaredHouseholdMember = joinsExistingHousehold && sharesHousehold;
284	        assignDerivedAttributes(owner, declaredHouseholdMember, householdMembers);
285	        this.clinicService.saveOwner(owner);
286	        ownerCreationAuditor.auditOwnerCreated(owner);
287	        welcomeNotifier.enqueueWelcome(owner);
288	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
289	        headers.setLocation(UriComponentsBuilder.newInstance()
290	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
291	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
292	    }
293	
294	    /**
295	     * Normalise the incoming fields of a freshly-mapped owner in place, applying
296	     * the canonical form each stored value must take: the address is trimmed,
297	     * whitespace-collapsed, upper-cased and its common abbreviations expanded, the
298	     * telephone is converted to E.164, any email is lower-cased and a missing
299	     * registration date defaults to today. Field-level rejections are reported here
300	     * rather than inline in {@link #addOwner}, and normalisation runs before any
301	     * household comparison so those comparisons see the canonical values.
302	     *
303	     * @param owner the freshly-mapped owner to normalise
304	     * @return {@code true} if the fields are valid, or {@code false} if the address
305	     *         is blank after normalisation, the telephone cannot form a valid
306	     *         E.164 number, or a supplied registration date is later than the
307	     *         server date, in which case the request must be rejected with
308	     *         {@code 400 Bad Request}
309	     */
310	    private boolean normalizeNewOwner(Owner owner) {
311	        if (!normalizeAddressFields(owner)) {
312	            return false;
313	        }
314	        String telephone = Telephones.toE164(owner.getTelephone());
315	        if (telephone == null) {
316	            return false;
317	        }
318	        owner.setTelephone(telephone);
319	        if (owner.getEmail() != null) {
320	            String email = owner.getEmail().toLowerCase();
321	            owner.setEmail(email);
322	            if (Owner.emailDomainIsDisposable(email)) {
323	                return false;
324	            }
325	        }
326	        if (!owner.postcodeValidForLocality()) {
327	            return false;
328	        }
329	        if (owner.getRegistrationDate() == null) {
330	            owner.setRegistrationDate(LocalDate.now());
331	        } else if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
332	            return false;
333	        }
334	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
335	        return true;
336	    }
337	
338	    /**
339	     * Normalise the owner's address fields in place to their canonical stored form
340	     * (trimmed, whitespace-collapsed, upper-cased and with common abbreviations
341	     * expanded; see {@link Owner#normalizeAddress(String)}), gathering the whole address
342	     * concern of {@link #normalizeNewOwner} in one place. The structured form is
343	     * preferred: when a non-blank {@code addressLine1} is supplied it (and any
344	     * {@code addressLine2}) is normalised, and the flat {@code address} is composed from
345	     * them — the normalised {@code addressLine1}, with a single space and the normalised
346	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the
347	     * flat {@code address} is normalised on its own, preserving backward compatibility.
348	     * Either way the canonicalised values are written back so every later household
349	     * comparison and read sees them.
350	     *
351	     * @param owner the freshly-mapped owner whose address fields are being normalised
352	     * @return {@code true} once an address is valid and stored, or {@code false} when
353	     *         neither a structured {@code addressLine1} nor a flat {@code address} is
354	     *         present after normalisation, in which case the request must be rejected
355	     *         with {@code 400 Bad Request}
356	     */
357	    private boolean normalizeAddressFields(Owner owner) {
358	        String addressLine1 = Owner.normalizeAddress(owner.getAddressLine1());
359	        if (!addressLine1.isEmpty()) {
360	            owner.setAddressLine1(addressLine1);
361	            String composed = addressLine1;
362	            String addressLine2 = Owner.normalizeAddress(owner.getAddressLine2());
363	            if (!addressLine2.isEmpty()) {
364	                owner.setAddressLine2(addressLine2);
365	                composed = addressLine1 + " " + addressLine2;
366	            }
367	            owner.setAddress(composed);
368	            return true;
369	        }
370	        String address = Owner.normalizeAddress(owner.getAddress());
371	        if (address.isEmpty()) {
372	            return false;
373	        }
374	        owner.setAddress(address);
375	        return true;
376	    }
377	
378	    /**
379	     * The fixed list of public holidays on which the clinic is closed. A registration
380	     * date that lands on one of these dates is treated the same as a weekend and rolled
381	     * forward past it (see {@link #rollToBusinessDay(LocalDate)}).
382	     */
383	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
384	        LocalDate.of(2026, 1, 1),
385	        LocalDate.of(2026, 1, 26),
386	        LocalDate.of(2026, 4, 25),
387	        LocalDate.of(2026, 12, 25),
388	        LocalDate.of(2026, 12, 28));
389	
390	    /**
391	     * Roll the given date forward to the next business day when it falls on a weekend or
392	     * a listed public holiday: a Saturday, Sunday or public holiday is advanced one day
393	     * at a time until a non-holiday weekday is reached, while a plain business day is
394	     * returned unchanged. Because rolling off a weekend can land on a holiday (and vice
395	     * versa), the advance repeats until the date is neither. Applied to the effective
396	     * registration date (whether supplied in the request or defaulted to the server date)
397	     * so that every value derived from it uses the adjusted business day.
398	     *
399	     * @param date the effective registration date
400	     * @return the same date if it is a non-holiday weekday, otherwise the next such day
401	     */
402	    private static LocalDate rollToBusinessDay(LocalDate date) {
403	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
404	            date = date.plusDays(1);
405	        }
406	        return date;
407	    }
408	
409	    /**
410	     * Whether the given date falls on a weekend (Saturday or Sunday).
411	     */
412	    private static boolean isWeekend(LocalDate date) {
413	        return switch (date.getDayOfWeek()) {
414	            case SATURDAY, SUNDAY -> true;
415	            default -> false;
416	        };
417	    }
418	
419	    /**
420	     * Find the existing owners that belong to the same household as the given owner,
421	     * i.e. share the same last name (compared case-insensitively with runs of
422	     * whitespace collapsed to a single space) and postcode, and so resolve to the same
423	     * deterministic {@code householdId}. Soft-deleted owners are excluded, so the result
424	     * holds only current household members. Evaluated before the new owner is saved, so
425	     * it reflects only owners that already existed at creation time; an owner joining no
426	     * existing household yields an empty list.
427	     *
428	     * @param owner the candidate owner being created
429	     * @return the current members of the owner's household, empty if none exists
430	     */
431	    private List<Owner> findHouseholdMembers(Owner owner) {
432	        return activeOwners()
433	            .filter(existing -> existing.sameHouseholdAs(owner))
434	            .toList();
435	    }
436	
437	    /**
438	     * Whether the candidate owner is a hard duplicate of an existing owner, i.e. it shares
439	     * the {@link Owner#getIdentityKey() identity key} (the SHA-256 digest over its
440	     * normalised telephone, lower-cased email and the Soundex of its last name) of a
441	     * current owner. Soft-deleted owners are ignored, so only the current owner population
442	     * is considered. A create whose identity key collides with an existing owner is
443	     * rejected with {@code 409 Conflict}. Evaluated after normalisation (so the
444	     * email-domain blocklist has already been applied) and before the owner is saved.
445	     *
446	     * @param owner the candidate owner being created, after normalisation
447	     * @return {@code true} if an existing, non-deleted owner shares the candidate's
448	     *         identity key
449	     */
450	    private boolean isDuplicateIdentity(Owner owner) {
451	        String identityKey = owner.getIdentityKey();
452	        return activeOwners()
453	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
454	    }
455	
456	    /**
457	     * The existing owners that are still active, i.e. those not flagged as soft-deleted.
458	     * Evaluated fresh against the saved owners each call, so it reflects only owners that
459	     * already existed at creation time; a soft-deleted owner is excluded and so takes no
460	     * part in the household resolution built on top of it. Isolating the exclusion here
461	     * keeps the "current owner population" one candidate is compared against in one place.
462	     *
463	     * @return a stream of the current, non-deleted owners
464	     */
465	    private Stream<Owner> activeOwners() {
466	        return this.clinicService.findAllOwners().stream()
467	            .filter(existing -> !Boolean.TRUE.equals(existing.getDeleted()));
468	    }
469	
470	    /**
471	     * Assign the owner's computed-at-creation attributes in place: its member id,
472	     * namesake count, bulk-signup warning and household size. Unlike
473	     * the {@code @Transient} attributes {@link Owner} recomputes on demand, these are
474	     * derived once here — from the owner's own (already normalised) fields and from the
475	     * wider owner population — and persisted with the owner. Run after normalisation,
476	     * household resolution and the identity-key check, so every value reflects the
477	     * owner's final field values and any household it has joined, and immediately before
478	     * the owner is saved.
479	     *
480	     * @param owner the candidate owner being created, after household resolution
481	     * @param declaredHouseholdMember whether this owner was created as a declared member
482	     *                                of an existing household (it shared an existing
483	     *                                owner's household and set {@code sharesHousehold}),
484	     *                                in which case it is not a suspected duplicate
485	     * @param householdMembers        the existing members of the owner's household at
486	     *                                creation time, used to derive its level ceiling
487	     */
488	    private void assignDerivedAttributes(Owner owner, boolean declaredHouseholdMember,
489	            List<Owner> householdMembers) {
490	        owner.setMemberId(deduplicatedMemberId(owner));
491	        owner.setNamesakeCount(countNamesakes(owner));
492	        owner.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
493	        owner.setCapacityWarning(cityApproachingCapacity(owner.getCity()));
494	        owner.setHouseholdSize(householdSize(owner));
495	        owner.setMembershipLevelCap(membershipLevelCap(householdMembers));
496	        assignPossibleDuplicate(owner, declaredHouseholdMember);
497	    }
498	
499	    /**
500	     * The household level ceiling to assign to the candidate owner: one above the highest
501	     * {@link Owner#getMembershipLevel() membership level} currently held by an existing
502	     * member of its household, or {@code null} when the household has no existing member
503	     * (so no ceiling applies). This bounds a new owner's reported membership level to at
504	     * most one above its household, keeping households from being outranked at the moment a
505	     * relative joins. Evaluated before the owner is saved, over the members that already
506	     * existed at creation time.
507	     *
508	     * @param householdMembers the existing members of the owner's household
509	     * @return the level ceiling to assign, or {@code null} when uncapped
510	     */
511	    private Integer membershipLevelCap(List<Owner> householdMembers) {
512	        return householdMembers.stream()
513	            .map(Owner::getMembershipLevel)
514	            .max(Comparator.naturalOrder())
515	            .map(max -> max + 1)
516	            .orElse(null);
517	    }
518	
519	    /**
520	     * Compute the member id to assign to the candidate owner, de-duplicated against
521	     * every existing owner's member id. The base id is the owner's computed
522	     * {@code <REGION><FY><HASH8><CHK>} (see {@link Owner#computeMemberId()}); when it does
523	     * not already belong to an existing owner it is used unchanged. Otherwise it collides,
524	     * and {@code -<n>} is appended with the smallest integer {@code n} of 2 or more that
525	     * yields an id no existing owner holds, so the returned member id is unique. Evaluated
526	     * before the owner is saved, so only pre-existing owners are considered.
527	     *
528	     * @param owner the candidate owner being created, after normalisation
529	     * @return the unique (de-duplicated) member id to assign
530	     */
531	    private String deduplicatedMemberId(Owner owner) {
532	        Set<String> existingIds = this.clinicService.findAllOwners().stream()
533	            .map(Owner::getMemberId)
534	            .filter(id -> id != null)
535	            .collect(java.util.stream.Collectors.toSet());
536	        String base = owner.computeMemberId();
537	        if (!existingIds.contains(base)) {
538	            return base;
539	        }
540	        int n = 2;
541	        while (existingIds.contains(base + "-" + n)) {
542	            n++;
543	        }
544	        return base + "-" + n;
545	    }
546	
547	    /**
548	     * Flag the candidate owner as a possible duplicate of an existing owner. A soft
549	     * match is an existing owner that shares this owner's last name (compared
550	     * case-insensitively) and postcode but carries a different (normalised) telephone.
551	     * When such a match exists the owner is still created, but with
552	     * {@code possibleDuplicate} true and {@code possibleDuplicateOf} set to the matching
553	     * owner's id; otherwise {@code possibleDuplicate} is false and no match id is
554	     * recorded. The earliest-created matching owner (lowest id) is chosen so the result
555	     * is deterministic. Evaluated before the owner is saved, so only pre-existing owners
556	     * are considered.
557	     *
558	     * <p>A declared household member — one that shared an existing owner's household
559	     * (same last name and postcode) and was admitted because it set
560	     * {@code sharesHousehold} — is never flagged: a declared member is not a suspected
561	     * duplicate, so its {@code possibleDuplicate} is false with no match id.
562	     *
563	     * @param owner the candidate owner being created, after household resolution
564	     * @param declaredHouseholdMember whether the owner is a declared household member
565	     */
566	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
567	        if (declaredHouseholdMember) {
568	            owner.setPossibleDuplicate(false);
569	            owner.setPossibleDuplicateOf(null);
570	            return;
571	        }
572	        Optional<Owner> match = this.clinicService.findAllOwners().stream()
573	            .filter(existing -> isSoftMatch(owner, existing))
574	            .min(Comparator.comparing(Owner::getId));
575	        if (match.isPresent()) {
576	            owner.setPossibleDuplicate(true);
577	            owner.setPossibleDuplicateOf(match.get().getId());
578	        } else {
579	            owner.setPossibleDuplicate(false);
580	            owner.setPossibleDuplicateOf(null);
581	        }
582	    }
583	
584	    /**
585	     * Whether an already-created {@code existing} owner is a soft-match for the candidate
586	     * {@code owner}: their {@link Owner#getIdentityKey() identity keys} differ (so they are
587	     * not a hard duplicate) yet the {@link Owner#soundex(String) Soundex} of their last
588	     * names and their postcodes match. This is the single soft-match test
589	     * {@link #assignPossibleDuplicate} applies across the owner population, isolated here so
590	     * the comparison that decides a suspected duplicate lives in one place. Two owners
591	     * sharing a last name and postcode but with different telephones therefore soft-match
592	     * rather than being rejected, since the telephone is part of the identity key.
593	     *
594	     * @param owner    the candidate owner being created
595	     * @param existing an already-created owner to test against it
596	     * @return {@code true} if {@code existing} is a soft-match for the candidate
597	     */
598	    private boolean isSoftMatch(Owner owner, Owner existing) {
599	        String postcode = owner.getPostcode();
600	        return postcode != null && postcode.equals(existing.getPostcode())
601	            && Owner.soundex(owner.getLastName()).equals(Owner.soundex(existing.getLastName()))
602	            && !owner.getIdentityKey().equals(existing.getIdentityKey());
603	    }
604	
605	    /**
606	     * Count how many owners belong to the given owner's household once this create
607	     * completes: the owners that already share its deterministic {@code householdId}
608	     * (derived from last name and postcode) plus the owner being created. Evaluated
609	     * after the owner's {@code householdId} has been assigned. An owner whose
610	     * {@code householdId} matches no existing owner is a household of one.
611	     *
612	     * @param owner the candidate owner being created, after household resolution
613	     * @return the household member count after this create (at least {@code 1})
614	     */
615	    private int householdSize(Owner owner) {
616	        String householdId = owner.getHouseholdId();
617	        if (householdId == null) {
618	            return 1;
619	        }
620	        long existing = this.clinicService.findAllOwners().stream()
621	            .filter(other -> householdId.equals(other.getHouseholdId()))
622	            .count();
623	        return (int) existing + 1;
624	    }
625	
626	    /**
627	     * Count the existing owners that share the given owner's first and last name,
628	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
629	     * before the new owner is saved, so the result reflects only owners that
630	     * already existed at creation time.
631	     *
632	     * @param owner the candidate owner being created
633	     * @return the number of existing namesakes
634	     */
635	    private int countNamesakes(Owner owner) {
636	        String firstName = normalizeName(owner.getFirstName());
637	        String lastName = normalizeName(owner.getLastName());
638	        return (int) this.clinicService.findAllOwners().stream()
639	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
640	                && normalizeName(existing.getLastName()).equals(lastName))
641	            .count();
642	    }
643	
644	    private static String normalizeName(String value) {
645	        return value == null ? "" : value.trim().toLowerCase();
646	    }
647	
648	    /**
649	     * Determine whether the given city has already reached its owner capacity, i.e.
650	     * it already contains 50 or more existing owners (compared case-insensitively
651	     * with surrounding whitespace trimmed). A new owner may not be created in a city
652	     * that is at capacity.
653	     *
654	     * @param city the candidate owner's city
655	     * @return {@code true} if the city already holds 50 or more owners
656	     */
657	    private boolean cityIsAtCapacity(String city) {
658	        return ownersInCity(city) >= 50;
659	    }
660	
661	    /**
662	     * Determine whether the given city is approaching its owner capacity, i.e. it
663	     * already contains between 40 and 49 existing owners (compared case-insensitively
664	     * with surrounding whitespace trimmed). This warns that the capacity limit of 50
665	     * is near; the hard rejection at 50 is handled separately by
666	     * {@link #cityIsAtCapacity(String)}. Evaluated before the new owner is saved, so
667	     * it reflects only owners that already existed at creation time.
668	     *
669	     * @param city the candidate owner's city
670	     * @return {@code true} if the city already holds between 40 and 49 owners
671	     */
672	    private boolean cityApproachingCapacity(String city) {
673	        long count = ownersInCity(city);
674	        return count >= 40 && count < 50;
675	    }
676	
677	    /**
678	     * Count the existing owners in the given city, compared case-insensitively with
679	     * surrounding whitespace trimmed.
680	     *
681	     * @param city the city to count owners for
682	     * @return the number of existing owners in that city
683	     */
684	    private long ownersInCity(String city) {
685	        String normalizedCity = normalizeName(city);
686	        return this.clinicService.findAllOwners().stream()
687	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizedCity))
688	            .count();
689	    }
690	
691	    /**
692	     * Determine whether the daily owner-creation limit has already been reached, i.e.
693	     * 100 or more owners already carry the given registration date. A new owner may
694	     * not be created once that day's cap is reached.
695	     *
696	     * @param registrationDate the registration date the new owner would be created with
697	     * @return {@code true} if 100 or more existing owners share that registration date
698	     */
699	    private boolean dailyLimitReached(LocalDate registrationDate) {
700	        long count = this.clinicService.findAllOwners().stream()
701	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
702	            .count();
703	        return count >= 100;
704	    }
705	
706	    /**
707	     * Determine whether more than 80 owners have already been created for the given
708	     * registration date, i.e. strictly more than 80 existing owners carry that date.
709	     * Evaluated before the new owner is saved, so it reflects only owners that
710	     * already existed at creation time.
711	     *
712	     * @param registrationDate the registration date the new owner would be created with
713	     * @return {@code true} if more than 80 existing owners share that registration date
714	     */
715	    private boolean bulkSignupWarning(LocalDate registrationDate) {
716	        long count = this.clinicService.findAllOwners().stream()
717	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
718	            .count();
719	        return count > 80;
720	    }
721	}
